<?php use Namira\PublicSearch; $renderSelect=function(string $name,array $rows,mixed $value,string $empty='همه'){$selected=false;echo '<select name="'.e($name).'" data-advanced-option><option value="">'.e($empty).'</option>';foreach($rows as $r){$id=(string)$r['id'];$active=(string)$value===$id;$selected=$selected||$active;echo '<option value="'.e($id).'" '.($active?'selected':'').'>'.e($r['title']).'</option>';}if((string)$value!==''&&!$selected)echo '<option selected value="'.e($value).'">انتخاب قبلی '.e($value).' — بدون نتیجه در این ترکیب</option>';echo '</select>';}; ?>
<?php if($options['axes']): ?><details class="advanced-group" open><summary>موضوع و دسته‌بندی‌های شهدا</summary><?php foreach($options['axes'] as $axis):$key=$axis['axis_key'];$selected=array_map('strval',(array)($f['axis'][$key]??[])); ?><fieldset class="advanced-axis"><legend><?= e($axis['title']) ?></legend><?php if(count($axis['options'])>8): ?><label class="advanced-option-search">جست‌وجو در گزینه‌ها<input type="search" data-option-search placeholder="جست‌وجوی <?= e($axis['title']) ?>"></label><?php endif ?><div class="advanced-option-list"><?php foreach($axis['options'] as $row): ?><label class="check" data-option-text="<?= e($row['title']) ?>"><input type="checkbox" name="axis[<?= e($key) ?>][]" value="<?= (int)$row['id'] ?>" <?= in_array((string)$row['id'],$selected,true)?'checked':'' ?> data-axis-mode="<?= e($axis['selection_mode']) ?>"><?= e($row['title']) ?></label><?php endforeach ?><?php foreach($selected as $id):if(in_array($id,array_map('strval',array_column($axis['options'],'id')),true))continue; ?><label class="check"><input type="checkbox" name="axis[<?= e($key) ?>][]" value="<?= e($id) ?>" checked>انتخاب قبلی <?= e($id) ?>؛ بدون نتیجه فعلی</label><?php endforeach ?></div></fieldset><?php endforeach ?></details><?php endif ?>
<?php foreach($options['places'] as $role=>$place): ?><details class="advanced-group" data-place-group="<?= e($role) ?>" <?= $role==='birth_place'||!empty($f['places'][$role])?'open':'' ?>><summary><?= e($place['title']) ?></summary><label class="check"><input type="checkbox" name="places[<?= e($role) ?>][present]" value="1" <?= !empty($f['places'][$role]['present'])?'checked':'' ?>>فقط پرونده‌های دارای اطلاعات <?= e($place['title']) ?></label><div class="fields"><?php foreach(['country'=>'کشور','province'=>'استان','county'=>'شهرستان','city'=>'شهر'] as $level=>$title):$value=$f['places'][$role][$level]??'';if(!$place['levels'][$level]&&$value==='')continue; ?><label><?= e($title) ?><span data-advanced-geo="<?= e($role.'.'.$level) ?>"><?php $renderSelect('places['.$role.']['.$level.']',$place['levels'][$level],$value); ?></span></label><?php endforeach ?></div><p class="hint">انتخاب والد، گزینه‌های پایین‌تر را محدود می‌کند. می‌توانید از هر سطح موجود جست‌وجو کنید؛ مکان نامشخص حدس زده نمی‌شود.</p></details><?php endforeach ?>
<?php if($options['dates']): ?><details class="advanced-group" <?= array_filter($f['dates']??[],fn($d)=>($d['from']??'')!==''||($d['to']??'')!=='')?'open':'' ?>><summary>تاریخ‌ها</summary><?php foreach($options['dates'] as $key=>$date): ?><fieldset><legend><?= e($date['title']) ?></legend><div class="fields"><label>تقویم<?php $rows=array_map(fn($r)=>['id'=>$r['calendar'],'title'=>['jalali'=>'شمسی','gregorian'=>'میلادی','hijri'=>'قمری'][$r['calendar']]],$date['calendars']);$calendar=$f['dates'][$key]['calendar']??($rows[0]['id']??'jalali');$renderSelect('dates['.$key.'][calendar]',$rows,$calendar,'انتخاب تقویم'); ?></label><?php foreach(['from'=>'از سال','to'=>'تا سال'] as $part=>$title): ?><label><?= e($title) ?><input type="text" inputmode="numeric" maxlength="4" name="dates[<?= e($key) ?>][<?= $part ?>]" value="<?= e($f['dates'][$key][$part]??'') ?>"></label><?php endforeach ?></div><p class="hint">فقط تاریخ‌های عمومی با سال معتبر جست‌وجو می‌شوند؛ تاریخ ناقص به تاریخ کامل تبدیل نمی‌شود.</p></fieldset><?php endforeach ?></details><?php endif ?>
<?php if($options['fields']): ?><details class="advanced-group" <?= array_intersect_key($f,array_flip(['first_name','last_name','archive_code','text_query']))?'open':'' ?>><summary>مشخصات و متن عمومی شهید</summary><div class="fields"><?php foreach(['first_name','last_name','archive_code'] as $key):if(!isset($options['fields'][$key])&&($f[$key]??'')==='')continue; ?><label><?= e($options['fields'][$key]??$key) ?><input name="<?= e($key) ?>" maxlength="<?= $key==='archive_code'?80:150 ?>" value="<?= e($f[$key]??'') ?>"></label><?php endforeach ?></div><?php $texts=array_intersect_key($options['fields'],PublicSearch::TEXT);if($texts||($f['text_query']??'')!==''): ?><div class="fields"><label>جست‌وجو در بخش<?php $renderSelect('text_field',array_map(fn($k,$v)=>['id'=>$k,'title'=>$v],array_keys($texts),array_values($texts)),$f['text_field']??array_key_first($texts),'انتخاب بخش متن'); ?></label><label>عبارت متن<input name="text_query" maxlength="150" value="<?= e($f['text_query']??'') ?>"></label></div><?php endif ?></details><?php endif ?>
<?php if($options['mediaAvailable']||Namira\Archive::hasMediaFilters($f)): ?><details class="advanced-group" <?= Namira\Archive::hasMediaFilters($f)?'open':'' ?>><summary>مشخصات تصاویر و آثار</summary><div class="fields"><?php foreach($options['media'] as $key=>$option):$rows=$option['rows'];$labels=match($key){'kind'=>['design'=>'تصویر طراحی‌شده','photo'=>'عکس اصلی','document'=>'سند تصویری'],'orientation'=>['portrait'=>'عمودی','landscape'=>'افقی','square'=>'مربع'],'download'=>['1'=>'قابل دریافت','0'=>'فقط نمایش'],default=>[]};foreach($rows as &$row)$row['title']=$labels[(string)$row['id']]??$row['title'];unset($row);if($key==='kind'&&count($rows)>1)$rows[]=['id'=>'all','title'=>$options['people']?'دارای تصویر از هر نوع':'همه انواع تصاویر']; ?><label><?= e($option['title']) ?><?php $renderSelect($key,$rows,$f[$key]??'',$key==='kind'&&!$options['people']?'طراحی‌شده؛ حالت پیش‌فرض':'همه'); ?></label><?php endforeach ?><label>عنوان یا توضیحات عمومی اثر<input name="media_q" maxlength="150" value="<?= e($f['media_q']??'') ?>"></label></div></details><?php endif ?>
<?php if($options['legacy']): ?><details class="advanced-group" <?= array_intersect_key($f,$options['legacy'])?'open':'' ?>><summary>اطلاعات قدیمی ثبت‌شده</summary><p class="hint">این مقادیر بدون تبدیل یا انتساب حدسی به ساختار جدید حفظ شده‌اند. مکان قدیمی الزاماً محل تولد نیست.</p><div class="fields"><?php foreach($options['legacy'] as $key=>$option): ?><label><?= e($option['title']) ?><?php $renderSelect($key,$option['rows'],$f[$key]??''); ?></label><?php endforeach ?></div></details><?php endif ?>
